import { PlayerController, QualityRadioGroupElement, playerContext, selectQuality, type PropertyValues } from '@videojs/html';

/** HTMLElement stand-in so the module can be imported during SSR. */
const Base: typeof QualityRadioGroupElement =
  typeof HTMLElement === 'undefined'
    ? (class {} as unknown as typeof QualityRadioGroupElement)
    : QualityRadioGroupElement;

/** Value of the automatic (ABR) option generated by Video.js. */
export const QUALITY_AUTO_VALUE = 'auto';

export interface RenditionLike {
  id: string;
  width?: number | undefined;
  height?: number | undefined;
  bitrate?: number | undefined;
}

function pixels(r: RenditionLike): number {
  if (r.width && r.height) return r.width * r.height;
  return r.height ?? r.width ?? 0;
}

/**
 * Menu order for quality options: Auto first, then the highest resolution down
 * to the lowest; equal resolutions by bitrate, highest first. Renditions
 * without a size go last. Independent of the manifest order; ties keep it.
 */
export function orderQualityValues(values: readonly string[], renditions: readonly RenditionLike[]): string[] {
  const byId = new Map(renditions.map((r) => [r.id, r]));
  const rank = (value: string) => {
    const r = byId.get(value);
    return { pixels: r ? pixels(r) : 0, bitrate: r?.bitrate ?? 0 };
  };
  const indexed = values.map((value, index) => ({ value, index, ...rank(value) }));
  indexed.sort((a, b) => {
    if (a.value === QUALITY_AUTO_VALUE) return -1;
    if (b.value === QUALITY_AUTO_VALUE) return 1;
    return b.pixels - a.pixels || b.bitrate - a.bitrate || a.index - b.index;
  });
  return indexed.map((entry) => entry.value);
}

/**
 * <esp-quality-radio-group>
 *
 * Video.js quality radio group whose items are kept in `orderQualityValues`
 * order. The DOM itself is reordered, so arrow key navigation follows the
 * visual order.
 */
export class EspQualityRadioGroupElement extends Base {
  /** Registration name (the inherited `tagName` is typed as the Video.js tag). */
  static readonly espTagName = 'esp-quality-radio-group';

  readonly #quality = new PlayerController(this, playerContext, selectQuality);

  override update(changed: PropertyValues): void {
    super.update(changed);
    const renditions = this.#quality.value?.videoRenditionList ?? [];
    const items = [...this.children].filter(
      (child): child is HTMLElement & { value: string } => child.localName === 'media-menu-radio-item',
    );
    if (items.length < 2) return;
    const order = orderQualityValues(
      items.map((item) => String(item.value)),
      renditions,
    );
    if (order.every((value, i) => String(items[i]!.value) === value)) return;
    // Items sit after the <template>; re-appending them in order moves only
    // these nodes. This runs once per rebuild of the list, not per sync.
    const byValue = new Map(items.map((item) => [String(item.value), item]));
    for (const value of order) {
      const item = byValue.get(value);
      if (item) this.append(item);
    }
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'esp-quality-radio-group': EspQualityRadioGroupElement;
  }
}
